    bool _gen = false;
    bool _save = false;

    public override bool GensBool { get => _gen; set => _gen = value; }
    public override string NameGen => $"[{Waybound.ModName}]: Desert Lab";
    public override bool Do_MakeGen(GenerationProgress progress) {
        progress.Message = Loc.GetChat("WorldGen.ThemisLaboratory");
        int x1 = GenVars.desertHiveLeft, x2 = GenVars.desertHiveRight, y1 = GenVars.desertHiveHigh, y2 = GenVars.desertHiveLow, x0 = (x1 + x2) / 2, y0 = (y1 + y2) / 2;

        for (int yScale = 0; yScale < 10000; yScale++) {
            if (!WorldGen.InWorld(x0, y0 + yScale)) {
                UI.ErrorMsg("Index out in array in Gen ThemisLaboratory");
                break; 
            };
            if (CheckWall(Main.tile[x0, y0 + yScale])) {
                if (CheckWall(Main.tile[x0 + 1, y0 + yScale]) && CheckWall(Main.tile[x0 - 1, y0 + yScale])) {
                    y0 += yScale - 80;
                    break;
                };
            };
            static bool CheckWall(Tile tile) => tile.WallType != WallID.Sandstone && tile.WallType != WallID.HardenedSand;
        };
        
        WayboundGenVars.ThemisLaboratoryX = x0;
        WayboundGenVars.ThemisLaboratoryY = y0;

        int width = _tiles.GetLength(1), height = _tiles.GetLength(0);

        for (int i = 0; i < width; i++) {
            for (int j = 0; j < height; j++) {
                int worldX = x0 - 33 + i;
                int worldY = y0 + 17 - j;

                if (!WorldGen.InWorld(worldX, worldY, 10)) { continue; }

                Tile tile = Framing.GetTileSafely(worldX, worldY);

                switch (_tiles[j, i]) {
                    case 0: break;
                    case 1: WorldHelper.ClearAndSaveWall(tile); break;
                    case 2: WorldHelper.PlaceTile(tile, TileType<DesertHunterBlock>()); break;
                    case 3: WorldHelper.PlaceTile(tile, TileType<DesertHunterTile>()); break;
                    case 4: WorldHelper.PlaceTile(tile, TileID.LogicGate, false, false, (mTile) => {
                        mTile.TileFrameX = 0;
                        mTile.TileFrameY = 36; 
                    }); break;
                    case 5: WorldHelper.PlaceTile(tile, TileType<HielitiumOre>()); break;
                };
                switch (_wales[j, i]) {
                    case 0: break;
                    case 1: tile.WallType = (ushort)WallType<DesertHunterBlockWall>(); break;
                    case 2: tile.WallType = (ushort)WallType<DesertHunterTileWall>(); break;
                };
                switch (_slope[j, i]) {
                    case 0: break;
                    case 1: tile.IsHalfBlock = true; break;
                    case 2: tile.Slope = SlopeType.SlopeDownRight; break;
                    case 3: tile.Slope = SlopeType.SlopeUpLeft; break;
                    case 4: tile.Slope = SlopeType.SlopeUpRight; break;
                    case 5: tile.Slope = SlopeType.SlopeDownLeft; break;
                };
            };
        };

        int[] arr = [ItemType<HelmetOfDesertHunter>(), ItemType<BreastplateOfDesertHunter>(), ItemType<LeggingsOfDesertHunter>()];
        int x = WayboundGenVars.ThemisLaboratoryX - 33, y = WayboundGenVars.ThemisLaboratoryY + 17;
        // Mannequin
        (_ted[0] = new([.. arr.Select(i => new Item(i))], new(x + 10, y - 21), 1)).Gen();
        (_ted[1] = new([.. arr.Select(i => new Item(i))], new(x + 53, y - 21))).Gen();
        // DesertHunterLamp
        WorldGen.PlaceObject(x + 2, y - 18, (ushort)TileType<DesertHunterLamp>());
        WorldGen.PlaceObject(x + 11, y - 4, (ushort)TileType<DesertHunterLamp>());
        WorldGen.PlaceObject(x + 19, y - 18, (ushort)TileType<DesertHunterLamp>());
        WorldGen.PlaceObject(x + 53, y - 4, (ushort)TileType<DesertHunterLamp>());
        WorldGen.PlaceObject(x + 62, y - 18, (ushort)TileType<DesertHunterLamp>());
        // DesertHunterTable
        WorldGen.Place3x2(x + 9, y - 4, (ushort)TileType<DesertHunterTable>());
        WorldGen.Place3x2(x + 20, y - 2, (ushort)TileType<DesertHunterTable>());
        WorldGen.Place3x2(x + 23, y - 2, (ushort)TileType<DesertHunterTable>());
        WorldGen.Place3x2(x + 41, y - 2, (ushort)TileType<DesertHunterTable>());
        WorldGen.Place3x2(x + 44, y - 2, (ushort)TileType<DesertHunterTable>());
        WorldGen.Place3x2(x + 55, y - 4, (ushort)TileType<DesertHunterTable>());
        // DesertHunterForge
        WorldGen.PlaceObject(x + 13, y - 3, (ushort)TileType<DesertHunterForge>());
        WorldGen.PlaceObject(x + 51, y - 3, (ushort)TileType<DesertHunterForge>());
        // DesertHunterChandelier
        WorldGen.Place3x3Wall(x + 5, y - 30, (ushort)TileType<DesertHunterChandelier>(), 0);
        WorldGen.Place3x3Wall(x + 32, y - 4, (ushort)TileType<DesertHunterChandelier>(), 0);
        WorldGen.Place3x3Wall(x + 59, y - 30, (ushort)TileType<DesertHunterChandelier>(), 0);
        // DesertHunterBookcase
        WorldGen.PlaceObject(x + 26, y - 2, TileType<DesertHunterBookcase>());
        WorldGen.PlaceObject(x + 29, y - 2, TileType<DesertHunterBookcase>());
        WorldGen.PlaceObject(x + 35, y - 2, TileType<DesertHunterBookcase>());
        WorldGen.PlaceObject(x + 38, y - 2, TileType<DesertHunterBookcase>());
        // DesertHunterClock
        WorldGen.PlaceObject(x + 26, y - 10, TileType<DesertHunterClock>());
        WorldGen.PlaceObject(x + 37, y - 10, TileType<DesertHunterClock>());
        // DesertHunterLantern
        WorldGen.Place1x2Top(x + 27, y - 28, (ushort)TileType<DesertHunterLantern>(), 0);
        WorldGen.Place1x2Top(x + 37, y - 28, (ushort)TileType<DesertHunterLantern>(), 0);
        // Chest
        int index = WorldGen.PlaceChest(x + 45, y - 18, (ushort)TileType<DesertHunterChest>());
        if (index != -1) { Loot(Main.chest[index].item, 0); };
        return true;
    }
    public override void PostUpdateWorld() {
        if (_ted[0] == null) {
            int[] arr = [ItemType<HelmetOfDesertHunter>(), ItemType<BreastplateOfDesertHunter>(), ItemType<LeggingsOfDesertHunter>()];
            int x = WayboundGenVars.ThemisLaboratoryX - 33, y = WayboundGenVars.ThemisLaboratoryY + 17;
            _ted[0] = new([.. arr.Select(i => new Item(i))], new(x + 10, y - 21), 1);
            _ted[1] = new([.. arr.Select(i => new Item(i))], new(x + 53, y - 21));
        };
        _ted[0].Set();
        _ted[1].Set();
    }
    public override void SaveWorldData(TagCompound tag) {
        tag[$"{Waybound.ModName}:Save bool"] = _save;
        if (!_save) {
            _ted[0].SaveWorldData(tag, "0");
            _ted[1].SaveWorldData(tag, "1");
        };
    }
    public override void LoadWorldData(TagCompound tag) {
        _save = tag.GetBool($"{Waybound.ModName}:Save bool");
        if (!_save && _ted[0] != null) {
            _ted[0].LoadWorldData(tag, "0");
            _ted[1].LoadWorldData(tag, "1");
            _save = true;
        };
    }
    static void Loot(Item[] items, int index) => new WUtils.Chest(items, index).SetItem(Tables.Set.IceLoot);
};